  "key_mechanisms": [
    {
      "mechanism": "Reduced or paused distributions",
      "explanation": "Rental income is usually pooled, reduced by operating costs (property management fees, insurance, property taxes, maintenance), and then distributed to token holders, often monthly or quarterly. A vacancy removes rent from that pool, so yields fall or pause."
    },
    {
      "mechanism": "Fixed costs continue during vacancy",
      "explanation": "Taxes, insurance, utilities, and maintenance often continue while a unit sits empty. If reserves are thin, distributions can turn negative or be suspended."
    },
    {
      "mechanism": "Reserve funds",
      "explanation": "Some platforms hold maintenance or vacancy reserves. Check whether such reserves exist, how large they are, and whether they are held in a segregated account."
    },
    {
      "mechanism": "Valuation and secondary market effects",
      "explanation": "Lower income can reduce the property's appraised value, which can lower the token's market price, especially where tokens trade on thin secondary markets. Token prices may also diverge from the underlying property value."
    },
    {
      "mechanism": "Liquidity risk",
      "explanation": "Even if the property is fine, holders may be unable to sell quickly, particularly if there are few buyers or the platform restricts transfers."
    }
  ],
